    @Test
    public void testCallRealMethod_LogicFlow() throws Throwable {
        // This test targets the specific logic:
        // 1. if (this.getMethod().getDeclaringClass().isInterface()) { ; }
        // 2. return realMethod.invoke(mock, rawArguments);

        // Setup
        TestService realObject = new TestService();
        Method method = TestService.class.getMethod("sayHello", String.class);
        Object[] args = new Object[]{"Tester"};

        // We simulate the components
        MockitoMethod mockitoMethod = mock(MockitoMethod.class);
        when(mockitoMethod.getMethod()).thenReturn(method);

        // Mocking the RealMethod behavior
        // Since RealMethod is an internal type, we use a mock or a stub
        RealMethod realMethod = (mock, arguments) -> method.invoke(realObject, arguments);

        // Constructing Invocation via reflection
        java.lang.reflect.Constructor<Invocation> constructor = Invocation.class.getDeclaredConstructor(
                Object.class, MockitoMethod.class, Object[].class, int.class, RealMethod.class);
        constructor.setAccessible(true);

        Invocation invocation = constructor.newInstance(realObject, mockitoMethod, args, 1, realMethod);

        // Execute
