        MyInterface mockInterface = mock(MyInterface.class);
        Method interfaceMethod = MyInterface.class.getMethod("dummy");

        MockitoMethod mockitoMethod = mock(MockitoMethod.class);
        when(mockitoMethod.getMethod()).thenReturn(interfaceMethod);

        RealMethod realMethod = (mock, arguments) -> null; // Do nothing
        Object[] args = new Object[0];

        java.lang.reflect.Constructor<Invocation> constructor = Invocation.class.getDeclaredConstructor(
                Object.class, MockitoMethod.class, Object[].class, int.class, RealMethod.class);
        constructor.setAccessible(true);

